def relu(input: torch.Tensor, inplace: bool=False) -> torch.Tensor:
    if inplace:
        output = input
    else:
        output = torch.empty_like(input)

    n_elements = input.numel()
    cuda.memcpy_htod(input.data_ptr(), input_ptr)
    cuda.memcpy_htod(output.data_ptr(), output_ptr)

    relu_kernel[input_ptr, output_ptr, n_elements]

    if inplace:
        return input
    else:
        return output

