def asin(input_tensor):
    """
    计算输入张量的反正弦（arcsine）值。

    参数：
        input_tensor (torch.Tensor): 输入的张量。

    返回：
        torch.Tensor: 输入张量每个元素的反正弦值。如果输入值超出[-1, 1]范围，返回NaN。
    """
    if not isinstance(input_tensor, torch.Tensor):
        raise ValueError('The input must be a torch.Tensor.')
    return torch.asin(input_tensor)

# Triton kernel
def asin_kernel(input_data, output_data, batch_size, num_elements):
    for i in range(batch_size * num_elements):
        input_value = input_data[i]
        if -1 <= input_value <= 1:
            output_data[i] = torch.asin(input_value)
        else:
            output_data[i] = float('nan')

# Wrapper function
def asin(input_tensor, *, out=None):
    if not isinstance(input_tensor, torch.Tensor):
        raise ValueError('The input must be a torch.Tensor.')

    batch_size = input_tensor.shape[0]
    num_elements = input_tensor.numel()

    if out is None:
        output_tensor = torch.empty_like(input_tensor)
    else:
        if not isinstance(out, torch.Tensor) or out.shape != (batch_size,):
